VALUES
  ('dish-xl-omelet-tomato', 'omelet-tomato', '{"ka":"ომლეტი პომიდორით","ru":"Омлет с томатами и овощами на пару","en":"Tomato Omelette with Steamed Vegetables"}'::jsonb, '{"ka":"ფაფუკი ომლეტი ცილით და ტკბილი პომიდვრით, გვერდზე ორთქლზე მოხარშული ბროკოლი, ყვავილოვანი კომბოსტო და ხრაშუნა კიტრი.","ru":"Пышный омлет с белком и сладкими томатами, рядом брокколи и цветная капуста на пару и хрустящий огурец.","en":"Fluffy egg-white omelette with sweet tomatoes, served with steamed broccoli, cauliflower and crisp cucumber."}'::jsonb, 'breakfast', '{"ka":"breakfast","ru":"breakfast","en":"breakfast"}'::jsonb, 'breakfast', 'mon', 0, 0, 275, 23, 9, 26, 380, '/images/meals/protein-pancakes.webp', '{"ka":["კვერცხი","კვერცხის ცილა","რძე 1,5%","პომიდორი","ბროკოლი","ყვავილოვანი კომბოსტო","კიტრი"],"ru":["Яйцо","Яичный белок","Молоко 1,5%","Томаты","Брокколи","Цветная капуста","Огурец"],"en":["Egg","Egg whites","Milk 1.5%","Tomatoes","Broccoli","Cauliflower","Cucumber"]}'::jsonb, '["კვერცხი","რძე"]'::jsonb, 'classic', '["site"]'::jsonb),
  ('dish-xl-chicken-cutlets-puree', 'chicken-cutlets-puree', '{"ka":"ქათმის კატლეტები პიურესა და ბოსტნეულით","ru":"Куриные котлеты с картофельным пюре и овощами","en":"Chicken Cutlets with Mash and Vegetables"}'::jsonb, '{"ka":"ნაზი ქათმის კატლეტები ყველით, ჰაეროვანი კარტოფილის პიურე, ბროკოლი და ბულგარული წიწაკა.","ru":"Нежные куриные котлеты с сыром, воздушное картофельное пюре, брокколи и сладкий перец.","en":"Tender cheesy chicken cutlets, airy potato purée, broccoli and sweet pepper."}'::jsonb, 'poultry', '{"ka":"poultry","ru":"poultry","en":"poultry"}'::jsonb, 'breakfast', 'tue', 0, 0, 392, 31, 8, 49, 390, '/images/meals/cutlet-kasha.webp', '{"ka":["ქათმის მკერდი","კვერცხი","მაგარი ყველი","კარტოფილი","რძე 1,5%","ბროკოლი","ბულგარული წიწაკა","ხახვი"],"ru":["Куриная грудка","Яйцо","Твёрдый сыр","Картофель","Молоко 1,5%","Брокколи","Болгарский перец","Лук"],"en":["Chicken breast","Egg","Hard cheese","Potato","Milk 1.5%","Broccoli","Bell pepper","Onion"]}'::jsonb, '["კვერცხი","რძე","გლუტენი"]'::jsonb, 'classic', '["site"]'::jsonb),
  ('dish-xl-cottage-pancakes', 'cottage-pancakes', '{"ka":"ხაჭოს პანკეიკები","ru":"Творожные панкейки с греческим йогуртом и ягодами","en":"Cottage Cheese Pancakes with Greek Yogurt"}'::jsonb, '{"ka":"ხაჭოს პანკეიკები ბერძნული იოგურტით და უშაქრო კენკროვანი მურაბით — ტკბილი დასაწყისი ცილით.","ru":"Пышные панкейки на твороге с греческим йогуртом и ягодным джемом без сахара — сладкий старт с белком.","en":"Soft cottage-cheese pancakes with Greek yogurt and sugar-free berry jam — a sweet start loaded with protein."}'::jsonb, 'breakfast', '{"ka":"breakfast","ru":"breakfast","en":"breakfast"}'::jsonb, 'breakfast', 'fri', 0, 0, 358, 31, 10, 32, 300, '/images/meals/syrniki-strawberry.webp', '{"ka":["ხაჭო 0%","კვერცხი","კეფირი 1%","ფქვილი","ბერძნული იოგურტი 2%","უშაქრო კენკროვანი მურაბა"],"ru":["Творог 0%","Яйцо","Кефир 1%","Мука","Греческий йогурт 2%","Ягодный джем без сахара"],"en":["Cottage cheese 0%","Egg","Kefir 1%","Flour","Greek yogurt 2%","Sugar-free berry jam"]}'::jsonb, '["კვერცხი","რძე","გლუტენი"]'::jsonb, 'classic', '["site"]'::jsonb),
  ('dish-xl-lazy-curd-balls', 'lazy-curd-balls', '{"ka":"ზარმაცი ხაჭოს ბურთულები (ვარენიკის ტიპის)","ru":"Ленивые вареники с творогом и ягодным соусом","en":"Lazy Cottage Cheese Dumplings with Berry Sauce"}'::jsonb, '{"ka":"ზარმაცი ვარენიკი ხაჭოსგან — ნაზი, მსუბუქი, არაჟნითა და კენკრით.","ru":"Ленивые вареники из обезжиренного творога — нежные, лёгкие, со сметаной и свежими ягодами.","en":"Lazy dumplings made from skim cottage cheese — tender and light, with sour cream and fresh berries."}'::jsonb, 'breakfast', '{"ka":"breakfast","ru":"breakfast","en":"breakfast"}'::jsonb, 'breakfast', 'thu', 0, 0, 299, 24, 7, 35, 330, '/images/meals/curd-casserole.webp', '{"ka":["ხაჭო 0%","კვერცხი","ბრინჯის ფქვილი","ხორბლის ფქვილი","არაჟანი 12%","კენკრა","უშაქრო მურაბა"],"ru":["Творог 0%","Яйцо","Рисовая мука","Пшеничная мука","Сметана 12%","Ягоды","Джем без сахара"],"en":["Cottage cheese 0%","Egg","Rice flour","Wheat flour","Sour cream 12%","Berries","Sugar-free jam"]}'::jsonb, '["კვერცხი","რძე","გლუტენი"]'::jsonb, 'classic', '["site"]'::jsonb),
  ('dish-xl-lazy-tolma-turkey', 'lazy-tolma-turkey', '{"ka":"ზარმაცი თოლმა (კომბოსტოს რულეტის სტილის)","ru":"Ленивая толма с индейкой","en":"Lazy Tolma with Turkey"}'::jsonb, '{"ka":"ზარმაცი თოლმა ინდაურის ფარშით, ბრინჯითა და ნაზი კომბოსტოთი პომიდვრის სოუსში.","ru":"Ленивая толма: фарш из индейки, рис и нежная капуста в томатном соусе — как дома, только полезнее.","en":"Lazy cabbage-roll tolma with turkey mince, rice and tender cabbage in tomato sauce."}'::jsonb, 'poultry', '{"ka":"poultry","ru":"poultry","en":"poultry"}'::jsonb, 'lunch', 'mon', 0, 0, 410, 31, 10, 49, 400, '/images/meals/chicken-roll-bulgur.webp', '{"ka":["ინდაურის ფარში","ბრინჯი","თეთრი კომბოსტო","სტაფილო","ხახვი","პომიდვრის პასტა"],"ru":["Фарш из индейки","Рис","Белокочанная капуста","Морковь","Лук","Томатная паста"],"en":["Turkey mince","Rice","White cabbage","Carrot","Onion","Tomato paste"]}'::jsonb, '[]'::jsonb, 'classic', '["site"]'::jsonb),
  ('dish-xl-fish-veg-crust-buckwheat', 'fish-veg-crust-buckwheat', '{"ka":"თევზი ბოსტნეულის „ქურქით“ წიწიბურასთან","ru":"Рыба под овощной «шубой» с гречкой","en":"Veggie-Crust Baked Fish with Buckwheat"}'::jsonb, '{"ka":"ტილაპია სტაფილოსა და ხახვის „ქურქში“, არაჟნით გამომცხვარი, გვერდზე მსხვრევადი წიწიბურა.","ru":"Филе тилапии под «шубой» из моркови и лука со сметаной, запечённое до нежности, с рассыпчатой гречкой.","en":"Tilapia fillet baked under a carrot-and-onion crust with a touch of sour cream, served with fluffy buckwheat."}'::jsonb, 'fish', '{"ka":"fish","ru":"fish","en":"fish"}'::jsonb, 'lunch', 'sat', 0, 0, 421, 34, 9, 51, 400, '/images/meals/fish-cutlet-potato.webp', '{"ka":["ტილაპიის ფილე","სტაფილო","ხახვი","არაჟანი 12%","წიწიბურა","კიტრი","პომიდორი"],"ru":["Филе тилапии","Морковь","Лук","Сметана 12%","Гречка","Огурец","Томаты"],"en":["Tilapia fillet","Carrot","Onion","Sour cream 12%","Buckwheat","Cucumber","Tomato"]}'::jsonb, '["თევზი","რძე"]'::jsonb, 'classic', '["site"]'::jsonb),
  ('dish-xl-potato-souffle-chicken-cheese', 'potato-souffle-chicken-cheese', '{"ka":"კარტოფილის სუფლე/ქათმის ყველით","ru":"Картофельное суфле с курицей, грибами и сыром","en":"Potato Soufflé with Chicken, Mushrooms & Cheese"}'::jsonb, '{"ka":"ჰაეროვანი კარტოფილის სუფლე ქათმით, შამპინიონითა და ყველის ქერქით.","ru":"Воздушное картофельное суфле с курицей и шампиньонами под сырной корочкой.","en":"Airy potato soufflé with chicken and champignons under a golden cheese crust."}'::jsonb, 'poultry', '{"ka":"poultry","ru":"poultry","en":"poultry"}'::jsonb, 'lunch', 'wed', 0, 0, 430, 35, 10, 50, 400, '/images/meals/chicken-cheese-buckwheat.webp', '{"ka":["კარტოფილი","ქათმის მკერდი","შამპინიონი","მაგარი ყველი","კვერცხის ცილა","ბერძნული იოგურტი 2%","რძე 1,5%"],"ru":["Картофель","Куриная грудка","Шампиньоны","Твёрдый сыр","Яичный белок","Греческий йогурт 2%","Молоко 1,5%"],"en":["Potato","Chicken breast","Champignons","Hard cheese","Egg whites","Greek yogurt 2%","Milk 1.5%"]}'::jsonb, '["კვერცხი","რძე"]'::jsonb, 'classic', '["site"]'::jsonb),
  ('dish-xl-braised-cabbage-turkey', 'braised-cabbage-turkey', '{"ka":"მოშუშული კომბოსტო ინდაურით","ru":"Тушёная капуста с индейкой","en":"Braised Cabbage with Turkey"}'::jsonb, '{"ka":"მოშუშული კომბოსტო ინდაურის ფარშით, სტაფილოთი და პაპრიკით — მსუბუქი და დამაკმაყოფილებელი.","ru":"Тушёная капуста с фаршем из индейки, морковью и паприкой — лёгкое и сытное блюдо.","en":"Slow-braised cabbage with turkey mince, carrot and paprika — light yet filling."}'::jsonb, 'poultry', '{"ka":"poultry","ru":"poultry","en":"poultry"}'::jsonb, 'lunch', 'sun', 0, 0, 337, 34, 9, 30, 420, '/images/meals/bulgur-mushrooms.webp', '{"ka":["ინდაურის ფარში","თეთრი კომბოსტო","სტაფილო","ხახვი","პომიდვრის პასტა","პაპრიკა"],"ru":["Фарш из индейки","Белокочанная капуста","Морковь","Лук","Томатная паста","Паприка"],"en":["Turkey mince","White cabbage","Carrot","Onion","Tomato paste","Paprika"]}'::jsonb, '[]'::jsonb, 'classic', '["site"]'::jsonb),
  ('dish-xl-beef-mushroom-stroganoff', 'beef-mushroom-stroganoff', '{"ka":"საქონლის ხორცი სოკოთი (ბეფსტროგანოვის სტილი)","ru":"Говядина с грибами в стиле бефстроганов","en":"Beef Stroganoff-Style with Mushrooms"}'::jsonb, '{"ka":"მჭლე საქონლის ხორცი შამპინიონით არაჟნისა და მდოგვის სოუსში, გვერდზე კარტოფილის პიურე და ბროკოლი.","ru":"Постная говядина с шампиньонами в сметанно-горчичном соусе, с картофельным пюре и брокколи.","en":"Lean beef with champignons in a sour-cream mustard sauce, served with potato purée and broccoli."}'::jsonb, 'meat', '{"ka":"meat","ru":"meat","en":"meat"}'::jsonb, 'lunch', 'fri', 0, 0, 409, 31, 9, 51, 380, '/images/meals/beef-demiglace-puree.webp', '{"ka":["საქონლის ხორცი","შამპინიონი","არაჟანი 10%","მდოგვი","ხახვი","კარტოფილი","ბროკოლი"],"ru":["Говядина","Шампиньоны","Сметана 10%","Горчица","Лук","Картофель","Брокколи"],"en":["Beef","Champignons","Sour cream 10%","Mustard","Onion","Potato","Broccoli"]}'::jsonb, '["რძე"]'::jsonb, 'classic', '["site"]'::jsonb),
  ('dish-xl-turkey-hedgehogs', 'turkey-hedgehogs', '{"ka":"ინდაურის „ზღარბები“ (მრგვალი ხინკლები სოუსში)","ru":"Ежики из индейки в соусе","en":"Turkey “Hedgehogs” in Tomato Sauce"}'::jsonb, '{"ka":"ინდაურის „ზღარბები“ ბრინჯით ნაზ პომიდვრისა და არაჟნის სოუსში, ახალ ბოსტნეულთან ერთად.","ru":"Нежные «ёжики» из индейки с рисом в томатно-сметанном соусе и свежими овощами.","en":"Tender turkey-and-rice “hedgehog” meatballs in a tomato–sour-cream sauce with fresh vegetables."}'::jsonb, 'poultry', '{"ka":"poultry","ru":"poultry","en":"poultry"}'::jsonb, 'dinner', 'tue', 0, 0, 341, 35, 5, 39, 380, '/images/meals/fish-cheese-risotto.webp', '{"ka":["ინდაურის ფარში","ბრინჯი","ხახვი","სტაფილო","პომიდვრის პასტა","არაჟანი 10%","ბულგარული წიწაკა"],"ru":["Фарш из индейки","Рис","Лук","Морковь","Томатная паста","Сметана 10%","Болгарский перец"],"en":["Turkey mince","Rice","Onion","Carrot","Tomato paste","Sour cream 10%","Bell pepper"]}'::jsonb, '["კვერცხი","რძე"]'::jsonb, 'classic', '["site"]'::jsonb),
  ('dish-xl-lentil-soup-puree', 'lentil-soup-puree', '{"ka":"ოსპის სუპი-პიურე","ru":"Чечевичный суп-пюре с курицей","en":"Red Lentil Cream Soup with Chicken"}'::jsonb, '{"ka":"წითელი ოსპის კრემ-სუპი ქათმით — თბილი, ხავერდოვანი, მსუბუქი ვახშმისთვის.","ru":"Бархатный суп-пюре из красной чечевицы с курицей — тёплый и лёгкий ужин.","en":"Velvety red-lentil cream soup with chicken — a warm, light dinner."}'::jsonb, 'poultry', '{"ka":"poultry","ru":"poultry","en":"poultry"}'::jsonb, 'dinner', 'wed', 0, 0, 335, 30, 9, 40, 450, '/images/meals/pumpkin-bluecheese.webp', '{"ka":["წითელი ოსპი","ქათმის მკერდი","კარტოფილი","სტაფილო","ხახვი","კარაქი"],"ru":["Красная чечевица","Куриная грудка","Картофель","Морковь","Лук","Сливочное масло"],"en":["Red lentils","Chicken breast","Potato","Carrot","Onion","Butter"]}'::jsonb, '["რძე"]'::jsonb, 'classic', '["site"]'::jsonb),
